#include "parallel.hpp"
#include "sycl_operation.hpp"
namespace p42parallel {
struct Guard {int error(ng::Args a)const{return sycl::atomic_ref<int32_t,sycl::memory_order::relaxed,sycl::memory_scope::device,sycl::access::address_space::global_space>(a.i(15)[0]).load();}void fail(ng::Args a)const{sycl::atomic_ref<int32_t,sycl::memory_order::relaxed,sycl::memory_scope::device,sycl::access::address_space::global_space>(a.i(15)[0]).store(1);}};
#include "parallel_gdn.inc"
template<iq3::Type T>struct Dense final:ownrt::SyclOperation{unsigned rows;
 sycl::event submit(sycl::queue&q,std::span<void*const> p,const std::vector<sycl::event>& deps)const override{auto w=static_cast<const uint8_t*>(p[0]);auto x=static_cast<const uint16_t*>(p[1]);auto y=static_cast<uint16_t*>(p[2]);unsigned n=rows;
 return q.submit([&](sycl::handler&h){h.depends_on(deps);h.parallel_for(sycl::nd_range<1>(n*32,32),p28::checked([=](sycl::nd_item<1> it)[[sycl::reqd_sub_group_size(32)]]{unsigned row=it.get_group_linear_id(),lane=it.get_local_linear_id();auto sg=it.get_sub_group();constexpr unsigned rb=6144+4*6144/(T==iq3::Type::Q6_K?16:32);auto v=dense_parts<T>(w+row*rb,x,lane);
 #pragma unroll
 for(unsigned p=0;p<4;++p)for(unsigned stride=1;stride<32;stride*=2){float rhs=sycl::select_from_group(sg,v[p],(lane+stride)%32);if(lane%(2*stride)==0)v[p]=v[p]+rhs;}
 if(lane==0)y[row]=iq3::bf16_bits((v[0]+v[1])+(v[2]+v[3]));}));});}
};
integrated::Launch submit_dense(ownrt::Device&d,const std::vector<integrated::Matrix>&m,const std::string&name,bool shared,unsigned variant){p28::validate(d,m,"p28.dense.wg32",shared,variant);if(name!="p42.dense.fourparts"||m.size()!=1||m[0].columns!=6144||variant!=7||m[0].routes||m[0].count!=1)throw std::invalid_argument("p42 dense shape");auto issue=[&]<iq3::Type T>(){Dense<T> k;k.rows=m[0].rows;std::array ids{m[0].w,m[0].x,m[0].y};auto e=d.compute(k,ids,{});return integrated::Launch{e,e,1};};if(m[0].type==iq3::Type::Q6_K)return issue.template operator()<iq3::Type::Q6_K>();if(m[0].type==iq3::Type::Q8_0)return issue.template operator()<iq3::Type::Q8_0>();throw std::invalid_argument("p42 dense type");}
template<int Stage>struct Route final:ownrt::SyclOperation{ng::Shape shape;
 sycl::event submit(sycl::queue&q,std::span<void*const>p,const std::vector<sycl::event>&deps)const override{ng::Args a;std::copy_n(p.begin(),19,a.p.begin());auto s=shape;auto scratch=static_cast<float*>(p[19]);return q.submit([&](sycl::handler&h){h.depends_on(deps);
 if constexpr(Stage!=2){auto n=specialised::work_items(s,Stage);h.parallel_for(sycl::range<1>(n),p28::checked([=](sycl::id<1> id){specialised::body<ng::route_gather,Stage,512>(s,a,id[0],scratch,Guard{});}));}
 else h.parallel_for(sycl::nd_range<1>(size_t(s.tokens)*512*32,32),p28::checked([=](sycl::nd_item<1>it)[[sycl::reqd_sub_group_size(32)]]{Guard guard;if(!a.i(18)[0]||guard.error(a))return;int pos=a.i(17)[0];unsigned logical=it.get_group_linear_id(),r=logical/512,j=logical%512,lane=it.get_local_linear_id();if(pos<0||pos>s.capacity-s.tokens){if(logical==0&&lane==0)guard.fail(a);return;}float* sums=scratch+r*(32+1024+10)+16;float* ex=sums+16;float den=specialised::upper(sums,16);unsigned rank=rank_lane<512>(ex,den,j,lane);auto sg=it.get_sub_group();for(unsigned stride=1;stride<32;stride*=2){unsigned rhs=sycl::select_from_group(sg,rank,(lane+stride)%32);if(lane%(2*stride)==0)rank+=rhs;}if(lane==0&&rank<10){float v=ex[j]/den;ex[1024+rank]=v;a.i(2)[r*10+rank]=j;for(int k=0;k<3;++k){a.i(5)[(r*10+rank)*3+k]=k==0?j:k==1?0:640;a.i(6)[(r*10+rank)*3+k]=k==0?j:k==1?0:2560;}}}));});}
};
template<int Flags>struct Gdn final:ownrt::SyclOperation{ng::Shape shape;sycl::event submit(sycl::queue&q,std::span<void*const>p,const std::vector<sycl::event>&deps)const override{ng::Args a;std::copy_n(p.begin(),19,a.p.begin());auto s=shape;return q.submit([&](sycl::handler&h){h.depends_on(deps);h.parallel_for(sycl::nd_range<1>(6144*32,32),p28::checked([=](sycl::nd_item<1>it)[[sycl::reqd_sub_group_size(32)]]{gdn_device<Flags>(s,a,it);}));});}};
integrated::Launch submit(ownrt::Device&d,ng::Shape s,std::span<const ownrt::Allocation>a,ownrt::Allocation scratch,std::span<const ownrt::Event>deps){ng::validate(s);if(a.size()!=19)throw std::invalid_argument("p42 bindings");auto need=ng::required_bytes(s);for(unsigned j=0;j<19;++j)if(d.arena.row(a[j]).bytes<need[j])throw std::invalid_argument("p42 short binding");if(d.arena.row(scratch).bytes<specialised::scratch_floats(s)*4)throw std::invalid_argument("p42 short scratch");std::vector<std::pair<unsigned,bool>> used=s.op==ng::gdn?std::vector<std::pair<unsigned,bool>>{{0,false},{1,false},{2,false},{3,false},{4,false},{5,false},{6,true},{7,true}}:std::vector<std::pair<unsigned,bool>>{{0,false},{1,false},{2,true},{3,true},{4,true},{5,true},{6,true}};
 used.insert(used.end(),{{15,true},{17,false},{18,false}});
 for(size_t i=0;i<used.size();++i){auto [slot,write]=used[i];const auto& binding=d.arena.row(a[slot]);if(!binding.live||binding.memory!=ownrt::Memory::device||reinterpret_cast<uintptr_t>(binding.pointer)%4)throw std::invalid_argument("p42 binding memory/alignment");if(a[slot]==scratch)throw std::invalid_argument("p42 scratch aliases binding");for(size_t j=0;j<i;++j){auto [other,other_write]=used[j];bool state_alias=s.op==ng::gdn&&slot==7&&other==5;if(a[slot]==a[other]&&(write||other_write)&&!state_alias)throw std::invalid_argument("p42 conflicting binding aliases");}}
 const auto& sr=d.arena.row(scratch);if(!sr.live||sr.memory!=ownrt::Memory::device||reinterpret_cast<uintptr_t>(sr.pointer)%4)throw std::invalid_argument("p42 scratch memory/alignment");
 std::array<ownrt::Allocation,20> bound;std::copy(a.begin(),a.end(),bound.begin());bound[19]=scratch;
 if(s.op==ng::route_gather){if(s.width!=512||s.extra!=10)throw std::invalid_argument("p42 route specialized width/top");integrated::Launch l{};auto issue=[&]<int Stage>(){Route<Stage> k;k.shape=s;std::array after{l.last};auto e=d.compute(k,bound,l.last?std::span<const ownrt::Event>(after):deps);if(!l.first)l.first=e;l.last=e;++l.passes;};issue.template operator()<0>();issue.template operator()<1>();issue.template operator()<2>();issue.template operator()<4>();return l;}
 if(s.op==ng::gdn){if(s.tokens!=1)throw std::invalid_argument("p42 gdn token1 only");auto issue=[&]<int F>(){Gdn<F> k;k.shape=s;auto e=d.compute(k,bound,deps);return integrated::Launch{e,e,1};};switch(s.flags){case 0:return issue.template operator()<0>();case 2:return issue.template operator()<2>();case 4:return issue.template operator()<4>();case 6:return issue.template operator()<6>();case 8:return issue.template operator()<8>();case 10:return issue.template operator()<10>();case 12:return issue.template operator()<12>();case 14:return issue.template operator()<14>();default:throw std::invalid_argument("p42 gdn flags");}}
 throw std::invalid_argument("p42 class");}
}
